 const normalize = value => String(value||"").trim().replace(/\s+/g," ").toLowerCase();
 const key = (r,kind) => JSON.stringify([r[0],r[1],r[3],r[4],...(kind==="branches"?[r[7],r[11],r[21]]:[r[7],r[8],r[9]]).map(v=>Math.round(v*100)/100)]);
 for(const fix of fixes){
   const rows=(data[fix.dataset]||[]).filter(r=>r[1]===fix.kind && r[0]===JSON.parse(fix.entries[0][0])[0]);
   const names=new Map(fix.entries);
   if(rows.length===names.size && rows.every(row=>names.has(key(row,fix.dataset)))){
     for(const row of rows) row[4]=names.get(key(row,fix.dataset));
   }
 }
 const byName=new Map(registry.map(item=>[normalize(item.name),item]));
 for(const row of data.solutions||[]){
   if(!String(row[0]).startsWith("2026-11"))continue;
   const item=byName.get(normalize(row[4]));
   if(item){row[2]=item.group;row[3]=item.region;row[4]=item.name;}
 }
 return data;
